49	export const MediaViewerModalContent: FC<Props> = ({ payload }) => {
50	  const { width: SCREEN_WIDTH, height: SCREEN_HEIGHT } = useWindowDimensions();
51	  const [showControls, setShowControls] = useState(true);
52	  const [currentIndex, setCurrentIndex] = useState(0);
53	  const localUriByEventIdRef = useRef<Map<string, string | null>>(new Map());
54	  const controlsAnimation = useRef(
55	    animateParallel(
56	      { translateY: [-120, 0], opacity: [0, 1] },
57	      { duration: 280 },
58	    ),
59	  ).current;
60	  const setPayload = useSetAtom(TimelineAtoms.mediaViewerPayload);
61	  const setImageInfoPayload = useSetAtom(TimelineAtoms.imageInfoPayload);
62	  const setVideoInfoPayload = useSetAtom(TimelineAtoms.videoInfoPayload);
63	
64	  const room = useMemo<RoomInterface | undefined>(() => {
65	    try {
66	      return MatrixCore.getRoom(payload.roomId);
67	    } catch {
68	      return undefined;
69	    }
70	  }, [payload.roomId]);
71	
72	  const { mediaItems, loading, reachedStart, paginationCount, loadMore } =
73	    useMediaTimeline({ room, roomId: payload.roomId });
74	
75	  /** Filtered events sorted newest-first. Falls back to the tapped event so
76	  the first frame isn't empty while the hook hydrates. */
77	  const events = useMemo<EventTimelineItem[]>(() => {
78	    const filtered = mediaItems.filter((item) => getMediaKind(item) !== null);
79	    return filtered.length === 0 ? [payload.initialEvent] : filtered;
80	  }, [mediaItems, payload.initialEvent]);
81	
82	  /** FlatList data: events + a trailing "older-edge" sentinel while more
83	  history remains. Swiping onto the sentinel triggers `loadMore`; incoming
84	  events land between the last real event and the sentinel, so the user
85	  slides from the spinner onto the newest item of the just-loaded batch.
86	  Suppressed during initial pagination so the seeded single-item render
87	  can't accidentally land on it. */
88	  const pages = useMemo<ViewerPage[]>(() => {
89	    const result: ViewerPage[] = events.map((event) => ({
90	      kind: "event",
91	      event,
92	    }));
93	    if (!loading && !reachedStart) result.push({ kind: "older-edge" });
94	    return result;
95	  }, [events, loading, reachedStart]);
96	
97	  /** Pages-index for the tapped event — resolved against the hydrated list. */
98	  const initialPageIndex = useMemo(() => {
99	    const idx = events.findIndex(
100	      (event) => getEventId(event) === payload.initialEventId,
101	    );
102	    return idx >= 0 ? idx : 0;
103	  }, [events, payload.initialEventId]);
104	
105	  const currentPage = pages[currentIndex];
106	  const currentEvent = currentPage?.kind === "event" ? currentPage.event : null;
107	  const currentKind = currentEvent ? getMediaKind(currentEvent) : null;
108	
109	  const senderName = useMemo(() => {
110	    if (!currentEvent) return null;
111	    if (currentEvent.senderProfile.tag === ProfileDetails_Tags.Ready) {
112	      return (
113	        currentEvent.senderProfile.inner.displayName ?? currentEvent.sender
114	      );
115	    }
116	    return currentEvent.sender;
117	  }, [currentEvent]);
118	
119	  const formattedDate = useMemo(() => {
120	    if (!currentEvent) return null;
121	    return format(Number(currentEvent.timestamp), "MMM d, HH:mm");
122	  }, [currentEvent]);
123	
124	  const onClose = useCallback(() => {
125	    setPayload(null);
126	  }, [setPayload]);
127	
128	  const handleSingleTap = useCallback(() => {
129	    setShowControls((prev) => !prev);
130	  }, []);
131	
132	  const handleViewableItemsChanged = useCallback(
133	    ({ viewableItems }: { viewableItems: { index: number | null }[] }) => {
134	      const first = viewableItems[0];
135	      if (first?.index == null) return;
136	      setCurrentIndex(first.index);
137	    },
138	    [],
139	  );
140	
141	  const handleLocalUriChange = useCallback(
142	    (eventId: string | null, uri: string | null) => {
143	      if (!eventId) return;
144	      localUriByEventIdRef.current.set(eventId, uri);
145	    },
146	    [],
147	  );
148	
149	  const handleOpenInfo = useCallback(() => {
150	    if (!currentEvent) return;
151	    const eventId = getEventId(currentEvent);
152	    const localUri = eventId
153	      ? (localUriByEventIdRef.current.get(eventId) ?? null)
154	      : null;
155	    if (currentKind === "image") {
156	      setImageInfoPayload({
157	        event: currentEvent,
158	        roomId: payload.roomId,
159	        localUri,
160	      });
161	    } else if (currentKind === "video") {
162	      setVideoInfoPayload({
163	        event: currentEvent,
164	        roomId: payload.roomId,
165	        localUri,
166	      });
167	    }
168	  }, [
169	    currentEvent,
170	    currentKind,
171	    payload.roomId,
172	    setImageInfoPayload,
173	    setVideoInfoPayload,
174	  ]);
175	
